<?php require_once __DIR__.'/_header.php';$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT v.title,t.token FROM videos v JOIN embed_tokens t ON t.video_id=v.id AND t.status=1 WHERE v.id=? LIMIT 1');$st->execute([$id]);$x=$st->fetch();if(!$x)exit('No active embed token');$src=app_url('embed/index.php?token='.$x['token']);$code='<iframe src="'.$src.'" style="width:100%;aspect-ratio:16/9;border:0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen loading="lazy"></iframe>';?><div class="page-head"><div><h1>Embed Player</h1><p>Generate the iframe code for an external website.</p></div></div><div class="panel" style="padding:22px"><h2><?=e($x['title'])?></h2><div style="aspect-ratio:16/9;background:#000;margin:18px 0;border-radius:8px;overflow:hidden"><iframe src="<?=e($src)?>" style="width:100%;height:100%;border:0" allow="autoplay;fullscreen;picture-in-picture" allowfullscreen></iframe></div><label>Embed Code<textarea rows="5" readonly><?=e($code)?></textarea></label><button onclick="navigator.clipboard.writeText(document.querySelector('textarea').value)">Copy Embed Code</button></div><?php require __DIR__.'/_footer.php';